function customizationSummary(){const rs=data().requirements||[],c={Fit:0,'Fit with configuration':0,'Process change':0,Extension:0,Integration:0,'Reporting / Analytics':0,Deferred:0,TBD:0};rs.forEach(r=>{const k=r.fitGap||'TBD';c[k]=(c[k]||0)+1});return c}
function renderGovernance(){const d=data(),c=customizationSummary(),raid=d.raid||[],dec=d.decisions||[];return `<div class="page-head"><div><h1>Governance & Traceability</h1><p>RAID, documented decisions and requirement-to-solution governance.</p></div><div class="button-row"><button class="btn" id="addRaid">+ RAID</button><button class="btn primary" id="addDecision">+ Decision</button></div></div><div class="grid kpi">${kpi('Open RAID',raid.filter(x=>!['Closed','Resolved'].includes(x.status)).length,'risks / assumptions / issues / dependencies')}${kpi('High / Critical',raid.filter(x=>!['Closed','Resolved'].includes(x.status)&&['High','Critical'].includes(x.severity)).length,'management attention')}${kpi('Requirements',(d.requirements||[]).length,'defined')}${kpi('Open decisions',dec.filter(x=>!['Closed','Decided'].includes(x.status)).length,'awaiting resolution')}${kpi('Steering decisions',dec.filter(x=>x.escalateToSteering===true||x.escalateToSteering==='Yes').length,'flagged for committee')}${kpi('Sources',(d.sources||[]).length,'baseline')}</div>
<div class="grid two-col"><div><div class="section-title"><h2>RAID register</h2><span>click an item to edit</span></div>${raidTable(raid)}</div><div><div class="section-title"><h2>D365 solution composition</h2><span>from requirements</span></div><div class="card pad"><div class="solution-meter">${Object.entries(c).map(([k,v])=>`<div><span>${esc(k)}</span><b>${v}</b></div>`).join('')}</div><div class="notice">Every Extension or Integration should have an explicit business justification, alternative considered and approval decision before build.</div></div></div></div>
<div class="section-title"><h2>Decision register</h2><span>project decisions are documented here</span></div>${decisionTable(dec)}`}
function raidTable(items){return `<div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Type</th><th>Severity</th><th>Stream</th><th>Description</th><th>Owner</th><th>Due</th><th>Status</th><th>Steering</th></tr></thead><tbody>${items.map(x=>`<tr data-edit-raid="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.type||'Risk')}</td><td>${badge(x.severity||'Medium')}</td><td>${esc(x.stream||'Program')}</td><td>${esc(x.title||x.description)}</td><td>${esc(x.owner||'')}</td><td>${esc(x.due||'')}</td><td>${esc(x.status||'Open')}</td><td>${x.escalateToSteering===true||x.escalateToSteering==='Yes'?badge('Escalated'):'—'}</td></tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty">No RAID entries yet.</div>'}</div>`}
function decisionTable(items){return `<div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Category</th><th>Decision / question</th><th>Stream</th><th>Owner</th><th>Recommendation</th><th>Due</th><th>Status</th><th>Steering</th></tr></thead><tbody>${items.map(x=>`<tr data-edit-decision="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.category||'Business process')}</td><td><b>${esc(x.title)}</b>${x.decisionOutcome?`<small>Decision: ${esc(x.decisionOutcome)}</small>`:''}</td><td>${esc(x.stream||'Program')}</td><td>${esc(x.owner)}</td><td>${esc(x.recommendation||'')}</td><td>${esc(x.due||'')}</td><td>${badge(x.status)}</td><td>${x.escalateToSteering===true||x.escalateToSteering==='Yes'?badge('Steering Committee'):'—'}</td></tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty">No decisions entered yet.</div>'}</div>`}
function renderArchitecture(){const d=data();return `<div class="page-head"><div><h1>Data, Integrations, Reporting & Controls</h1><p>Cross-functional readiness registers that support design, build, testing and cutover.</p></div></div>${registerSection('Master Data',(d.dataObjects||[]),'addDataObject','data-object')}${registerSection('Integrations',(d.integrations||[]),'addIntegration','integration')}${registerSection('Reporting',(d.reports||[]),'addReport','report')}${registerSection('Controls',(d.controls||[]),'addControl','control')}`}
function registerSection(title,items,buttonId,kind){const heads={
 'data-object':['ID','Object','Stream','Owner','Source','Quality','Mapping','Cleansing','Migration','Cutover'],
 integration:['ID','Interface','Stream','Owner','Current → Target','Criticality','Build','SIT','UAT','Status'],
 report:['ID','Report','Stream','Owner','Current source','Target','Disposition','Status'],
 control:['ID','Control','Stream / Process','Owner','Type','Automation','Current → Future','SoD','Status']
}[kind];const rows=items.map(x=>{if(kind==='data-object')return `<tr data-edit-data="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.object)}</td><td>${esc(x.stream||'ALL')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.sourceSystem||'')}</td><td>${esc(x.quality||'TBD')}</td><td>${esc(x.mappingStatus||'Not Started')}</td><td>${esc(x.cleansingStatus||'Not Started')}</td><td>${esc(x.migrationStatus||'Not Started')}</td><td>${x.cutoverReady===true||x.cutoverReady==='Yes'?badge('Ready'):'—'}</td></tr>`;if(kind==='integration')return `<tr data-edit-integration="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.interface)}</td><td>${esc(x.stream||'ALL')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.currentSystem||'')} → ${esc(x.targetSystem||'D365')}</td><td>${badge(x.criticality||'Medium')}</td><td>${esc(x.buildStatus||'Not Started')}</td><td>${esc(x.sitStatus||'Not Started')}</td><td>${esc(x.uatStatus||'Not Started')}</td><td>${esc(x.status||'Open')}</td></tr>`;if(kind==='report')return `<tr data-edit-report="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.report)}</td><td>${esc(x.stream||'ALL')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.currentSource||'')}</td><td>${esc(x.targetType||'TBD')}</td><td>${esc(x.disposition||'TBD')}</td><td>${esc(x.status||'Open')}</td></tr>`;return `<tr data-edit-control="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.control)}</td><td>${esc(x.stream||'ALL')} · ${esc(x.process||'')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.controlType||'')}</td><td>${esc(x.automation||'')}</td><td>${esc(x.currentSystem||'')} → ${esc(x.futureControl||'')}</td><td>${esc(x.sodImpact||'TBD')}</td><td>${esc(x.status||'Open')}</td></tr>`}).join('');return `<div class="section-title"><h2>${esc(title)}</h2><button class="btn primary" id="${buttonId}">+ Add</button></div><div class="card table-wrap"><table class="data-table"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table>${items.length?'':'<div class="empty">No entries yet. The register is ready for workshops.</div>'}</div>`}
function renderSteering(){const d=data(),h=programHealth(),escs=(d.escalations||[]).filter(x=>!['Closed','Resolved'].includes(x.status)),steerDec=(d.decisions||[]).filter(x=>(x.escalateToSteering===true||x.escalateToSteering==='Yes')&&!['Closed'].includes(x.status)),highRaid=(d.raid||[]).filter(x=>!['Closed','Resolved'].includes(x.status)&&['High','Critical'].includes(x.severity)),up=(d.milestones||[]).filter(m=>{const n=daysFromToday(m.end);return n!==null&&n>=0&&n<=45}),recent=(d.decisions||[]).filter(x=>['Decided','Closed'].includes(x.status)).sort((a,b)=>String(b.decisionDate||'').localeCompare(String(a.decisionDate||''))).slice(0,8);return `<div class="page-head"><div><h1>Steering Committee View</h1><p>Executive agenda: program health, escalations, decisions, top RAID and near-term milestones.</p></div><button class="btn primary" id="addEscalation">+ Escalate to Steering Committee</button></div><div class="steering-banner ${h.overall.toLowerCase()}"><div><span>Overall program health</span><strong>${h.overall}</strong></div><div><span>Open escalations</span><strong>${escs.length}</strong></div><div><span>Decisions for committee</span><strong>${steerDec.length}</strong></div><div><span>High / critical RAID</span><strong>${highRaid.length}</strong></div></div>
<div class="section-title"><h2>Steering Committee escalations</h2><span>items explicitly raised for committee action</span></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Type</th><th>Escalation</th><th>Reason / impact</th><th>Recommendation</th><th>Owner</th><th>Committee date</th><th>Status</th></tr></thead><tbody>${escs.map(x=>`<tr data-edit-escalation="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.type||'Decision')}</td><td><b>${esc(x.title)}</b>${x.relatedId?`<small>Related: ${esc(x.relatedId)}</small>`:''}</td><td>${esc(x.reason||x.impact||'')}</td><td>${esc(x.recommendation||'')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.committeeDate||'TBD')}</td><td>${badge(x.status||'Open')}</td></tr>`).join('')}</tbody></table>${escs.length?'':'<div class="empty">No open steering escalations.</div>'}</div>
<div class="grid two-col"><div><div class="section-title"><h2>Decisions requiring committee action</h2><span>${steerDec.length}</span></div>${decisionTable(steerDec)}</div><div><div class="section-title"><h2>Top RAID</h2><span>${highRaid.length}</span></div>${raidTable(highRaid)}</div></div>
<div class="grid two-col"><div><div class="section-title"><h2>Next 45 days</h2><span>program milestones</span></div><div class="card pad">${up.map(m=>`<div class="outlook-item"><b>${esc(m.name)}</b><small>${esc(m.start)} → ${esc(m.end)} · ${esc(m.status)}</small></div>`).join('')||'<div class="empty">No milestone ends in the next 45 days.</div>'}</div></div><div><div class="section-title"><h2>Decisions already documented</h2><span>latest</span></div><div class="card pad">${recent.map(x=>`<div class="decision-log-item" data-edit-decision="${x.id}"><span>${esc(x.id)} · ${esc(x.decisionDate||'')}</span><b>${esc(x.title)}</b><small>${esc(x.decisionOutcome||x.status)}</small></div>`).join('')||'<div class="empty">No decided items yet.</div>'}</div></div></div>`}
function gantt(items){const dates=items.flatMap(x=>[x.start,x.end]).filter(Boolean).map(x=>new Date(x+'T00:00:00'));if(!dates.length)return'<div class="card empty">No dated items.</div>';const min=new Date(Math.min(...dates)),max=new Date(Math.max(...dates)),span=Math.max(1,max-min);return `<div class="card gantt"><div class="gantt-head"><span>${min.toLocaleDateString()}</span><span>${max.toLocaleDateString()}</span></div>${items.filter(x=>x.start&&x.end).map(x=>{const a=new Date(x.start+'T00:00:00'),b=new Date(x.end+'T00:00:00'),left=100*(a-min)/span,width=Math.max(1,100*(b-a)/span);return `<div class="gantt-row"><div class="gantt-label"><b>${esc(x.name)}</b><small>${esc(x.stream||'')} · ${esc(x.status||'')}</small></div><div class="gantt-track"><div class="gantt-bar" style="left:${left}%;width:${width}%"></div></div></div>`}).join('')}</div>`}
function renderRoadmap(){const d=data(),m=d.milestones||[],open=(d.tasks||[]).filter(t=>!['Closed','Approved'].includes(t.status));return `<div class="page-head"><div><h1>Program Roadmap</h1><p>Program phases plus workstream delivery schedule. Baseline dates remain editable.</p></div><button class="btn primary" id="addMilestone">+ Milestone</button></div><div class="section-title"><h2>Program phases</h2><span>18-month implementation horizon</span></div>${gantt(m)}<div class="section-title"><h2>Workstream schedule</h2><span>open tasks by forecast date</span></div>${gantt(open.map(t=>({name:t.title,stream:t.stream,start:t.start,end:t.forecastDue||t.due,status:t.status})))}<div class="section-title"><h2>Milestones</h2></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Milestone</th><th>Stream</th><th>Start</th><th>End</th><th>Status</th></tr></thead><tbody>${m.map(x=>`<tr data-edit-milestone="${x.id}"><td>${esc(x.name)}</td><td>${esc(x.stream)}</td><td>${esc(x.start)}</td><td>${esc(x.end)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`}
